            probabilityA\n        ) / probabilityB\n    }\n\n\n    // ========================================================\n    // COMBINATORICS\n    // ========================================================\n\n    // n!\n\n    static fn factorial(n) {\n\n        return Math.factorial(n)\n    }\n\n\n    // nPr\n\n    static fn permutation(n, r) {\n\n        if (n < 0 || r < 0 || r > n) {\n            throw 'Invalid permutation values'\n        }\n\n        return Math.factorial(n) /\n            Math.factorial(n - r)\n    }\n\n\n    // nCr\n\n    static fn combination(n, r) {\n\n        if (n < 0 || r < 0 || r > n) {\n            throw 'Invalid combination values'\n        }\n\n        return Math.factorial(n) /\n            (\n                Math.factorial(r) *\n                Math.factorial(n - r)\n            )\n    }\n\n\n    // ========================================================\n    // BINOMIAL DISTRIBUTION\n    // ========================================================\n\n    // P(X = k)\n    //\n    // C(n,k) * p^k * (1-p)^(n-k)\n\n    static fn binomial(\n        n,\n        k,\n        probability\n    ) {\n\n        if (n < 0) {\n            throw 'Number of trials cannot be negative'\n        }\n\n        if (k < 0 || k > n) {\n            throw 'Success count must be between 0 and n'\n        }\n\n        if (\n            probability < 0 ||\n            probability > 1\n        ) {\n            throw 'Probability must be between 0 and 1'\n        }\n\n        return Math.combination(n, k) *\n            Math.pow(\n                probability,\n                k\n            ) *\n            Math.pow(\n                1 - probability,\n                n - k\n            )\n    }\n\n\n    // Probability of at most k successes\n\n    static fn binomialAtMost(\n        n,\n        k,\n        probability\n    ) {\n\n        if (k < 0) {\n            return 0\n        }\n\n        if (k >= n) {\n            return 1\n        }\n\n        auto total = 0\n\n        loop (k + 1, i) {\n\n            total =\n                total +\n                Probability.binomial(\n                    n,\n                    i,\n                    probability\n                )\n        }\n\n        return total\n    }\n\n\n    // Probability of at least k successes\n\n    static fn binomialAtLeast(\n        n,\n        k,\n        probability\n    ) {\n\n        if (k <= 0) {\n            return 1\n        }\n\n        if (k > n) {\n            return 0\n        }\n\n        return 1 -\n            Probability.binomialAtMost(\n                n,\n                k - 1,\n                probability\n            )\n    }\n\n\n    // ========================================================\n    // EXPECTED VALUE\n    // ========================================================\n\n    // E(X) = Σ xP(x)\n\n    static fn expectedValue(values, probabilities) {\n\n        if (\n            values.length() !=\n            probabilities.length()\n        ) {\n            throw 'Values and probabilities must have the same length'\n        }\n\n        if (values.length() == 0) {\n            throw 'Collections cannot be empty'\n        }\n\n        auto total = 0\n        auto probabilityTotal = 0\n\n        loop (values.length(), i) {\n\n            total =\n                total +\n                values[i] *\n                probabilities[i]\n\n            probabilityTotal =\n                probabilityTotal +\n                probabilities[i]\n        }\n\n        if (\n            probabilityTotal < 0.999999 ||\n            probabilityTotal > 1.000001\n        ) {\n            throw 'Probabilities must sum to 1'\n        }\n\n        return total\n    }\n\n\n    // ========================================================\n    // VARIANCE OF DISCRETE DISTRIBUTION\n    // ========================================================\n\n    static fn variance(values, probabilities) {\n\n        auto mean =\n            Probability.expectedValue(\n                values,\n                probabilities\n            )\n\n        auto total = 0\n\n        loop (values.length(), i) {\n\n            auto difference =\n                values[i] - mean\n\n            total =\n                total +\n                difference *\n                difference *\n                probabilities[i]\n        }\n\n        return total\n    }\n\n\n    static fn standardDeviation(\n        values,\n        probabilities\n    ) {\n\n        return Math.sqrt(\n            Probability.variance(\n                values,\n                probabilities\n            )\n        )\n    }\n\n\n    // ========================================================\n    // UNIFORM DISTRIBUTION\n    // ========================================================\n\n    // Continuous uniform PDF\n\n    static fn uniform(\n        value,\n        minimum,\n        maximum\n    ) {\n\n        if (maximum <= minimum) {\n            throw 'Maximum must be greater than minimum'\n        }\n\n        if (\n            value < minimum ||\n            value > maximum\n        ) {\n            return 0\n        }\n\n        return 1 /\n            (\n                maximum - minimum\n            )\n    }\n\n\n    // Uniform CDF\n\n    static fn uniformCdf(\n        value,\n        minimum,\n        maximum\n    ) {\n\n        if (maximum <= minimum) {\n            throw 'Maximum must be greater than minimum'\n        }\n\n        if (value <= minimum) {\n            return 0\n        }\n\n        if (value >= maximum) {\n            return 1\n        }\n\n        return (\n            value - minimum\n        ) / (\n            maximum - minimum\n        )\n    }\n\n\n    // ========================================================\n    // NORMAL DISTRIBUTION\n    // ========================================================\n\n    // Probability density function\n    //\n    // 1 / sqrt(2πσ²)\n    // * e^(-(x-μ)² / 2σ²)\n\n    static fn normal(\n        value,\n        mean,\n        standardDeviation\n    ) {\n\n        if (standardDeviation <= 0) {\n            throw 'Standard deviation must be greater than zero'\n        }\n\n        auto difference =\n            value - mean\n\n        auto exponent =\n            -(\n                difference *\n                difference\n            ) /\n            (\n                2 *\n                standardDeviation *\n                standardDeviation\n            )\n\n        auto denominator =\n            standardDeviation *\n            Math.sqrt(\n                2 * PI\n            )\n\n        return Math.exp(exponent) /\n            denominator\n    }\n\n\n    // Normal CDF approximation.\n    //\n    // Returns P(X <= value)\n\n    static fn normalCdf(\n        value,\n        mean,\n        standardDeviation\n    ) {\n\n        if (standardDeviation <= 0) {\n            throw 'Standard deviation must be greater than zero'\n        }\n\n        auto z =\n            (\n                value - mean\n            ) /\n            (\n                standardDeviation *\n                Math.sqrt(2)\n            )\n\n        // Approximation of erf(z)\n        auto sign = 1\n\n        if (z < 0) {\n            sign = -1\n            z = -z\n        }\n\n        auto t =\n            1 /\n            (\n                1 +\n                0.3275911 * z\n            )\n\n        auto a1 = 0.254829592\n        auto a2 = -0.284496736\n        auto a3 = 1.421413741\n        auto a4 = -1.453152027\n        auto a5 = 1.061405429\n\n        auto polynomial =\n            (\n                (\n                    (\n                        (\n                            a5 * t +\n                            a4\n                        ) * t +\n                        a3\n                    ) * t +\n                    a2\n                ) * t +\n                a1\n            ) * t\n\n        auto erf =\n            1 -\n            polynomial *\n            Math.exp(\n                -z * z\n            )\n\n        erf = erf * sign\n\n        return (\n            1 + erf\n        ) / 2\n    }\n\n\n    // ========================================================\n    // BERNOULLI\n    // ========================================================\n\n    static fn bernoulli(value, probability) {\n\n        if (\n            probability < 0 ||\n            probability > 1\n        ) {\n            throw 'Probability must be between 0 and 1'\n        }\n\n        if (value == 1) {\n            return probability\n        }\n\n        if (value == 0) {\n            return 1 - probability\n        }\n\n        throw 'Bernoulli value must be 0 or 1'\n    }\n\n\n    // ========================================================\n    // GEOMETRIC DISTRIBUTION\n    // ========================================================\n\n    // Probability that first success occurs on kth trial.\n    //\n    // P(X=k) = (1-p)^(k-1) * p\n\n    static fn geometric(k, probability) {\n\n        if (k < 1) {\n            throw 'Trial number must be at least 1'\n        }\n\n        if (\n            probability <= 0 ||\n            probability > 1\n        ) {\n            throw 'Probability must be greater than 0 and at most 1'\n        }\n\n        return Math.pow(\n            1 - probability,\n            k - 1\n        ) * probability\n    }\n\n\n    // ========================================================\n    // POISSON DISTRIBUTION\n    // ========================================================\n\n    // P(X=k) = e^-λ * λ^k / k!\n\n    static fn poisson(k, lambda) {\n\n        if (k < 0) {\n            throw 'k cannot be negative'\n        }\n\n        if (lambda <= 0) {\n            throw 'Lambda must be greater than zero'\n        }\n\n        return Math.exp(-lambda) *\n            Math.pow(lambda, k) /\n            Math.factorial(k)\n    }\n\n\n    // ========================================================\n    // HYPERGEOMETRIC DISTRIBUTION\n    // ========================================================\n\n    // Population = N\n    // Successes = K\n    // Sample = n\n    // Observed successes = k\n\n    static fn hypergeometric(\n        population,\n        successes,\n        sample,\n        observed\n    ) {\n\n        if (\n            population < 0 ||\n            successes < 0 ||\n            sample < 0 ||\n            observed < 0\n        ) {\n            throw 'Values cannot be negative'\n        }\n\n        if (successes > population) {\n            throw 'Successes cannot exceed population'\n        }\n\n        if (sample > population) {\n            throw 'Sample cannot exceed population'\n        }\n\n        if (observed > successes) {\n            return 0\n        }\n\n        if (\n            sample - observed >\n            population - successes\n        ) {\n            return 0\n        }\n\n        auto numerator =\n            Math.combination(\n                successes,\n                observed\n            ) *\n            Math.combination(\n                population - successes,\n                sample - observed\n            )\n\n        auto denominator =\n            Math.combination(\n                population,\n                sample\n            )\n\n        return numerator / denominator\n    }\n\n\n    // ========================================================\n    // SAMPLE MEAN DISTRIBUTION\n    // ========================================================\n\n    static fn standardError(\n        standardDeviation,\n        sampleSize\n    ) {\n\n        if (sampleSize <= 0) {\n            throw 'Sample size must be greater than zero'\n        }\n\n        return standardDeviation /\n            Math.sqrt(sampleSize)\n    }\n\n\n    // ========================================================\n    // ODDS\n    // ========================================================\n\n    // Probability -> odds\n\n    static fn probabilityToOdds(probability) {\n\n        if (\n            probability < 0 ||\n            probability > 1\n        ) {\n            throw 'Probability must be between 0 and 1'\n        }\n\n        if (probability == 1) {\n            throw 'Odds are infinite when probability is 1'\n        }\n\n        return probability /\n            (\n                1 - probability\n            )\n    }\n\n\n    // Odds -> probability\n\n    static fn oddsToProbability(odds) {\n\n        if (odds < 0) {\n            throw 'Odds cannot be negative'\n        }\n\n        return odds /\n            (\n                1 + odds\n            )\n    }\n\n\n    // ========================================================\n    // PERCENT\n    // ========================================================\n\n    static fn toPercent(probability) {\n\n        if (\n            probability < 0 ||\n            probability > 1\n        ) {\n            throw 'Probability must be between 0 and 1'\n        }\n\n        return probability * 100\n    }\n\n\n    static fn fromPercent(percent) {\n\n        if (\n            percent < 0 ||\n            percent > 100\n        ) {\n            throw 'Percent must be between 0 and 100'\n        }\n\n        return percent / 100\n    }\n}",
    'udpsocket': "/// A User Datagram Protocol (UDP) socket.\n/// \n/// UDPSocket allows you to send and receive datagrams connectionlessly over a network.\nclass UDPSocket {\n  static outer async fn bind(host, port)\n  outer async fn send(data, host, port)\n  outer async fn sendBytes(buffer, host, port)\n  outer async fn receive()\n  outer async fn receiveBytes()\n  outer async fn close()\n}\n",
    'io': "class File {\n    String path = \"\"\n    \n    fn init(path) {\n        this.path = path\n    }\n\n    outer async fn create()\n    outer async fn delete()\n    outer async fn exists()\n    outer async fn readAsString()\n    outer async fn writeAsString(content)\n    outer async fn appendAsString(content)\n    outer async fn readAsBytes()\n    outer async fn writeAsBytes(buffer)\n    outer async fn copy(newPath)\n    outer async fn rename(newPath)\n}\n\nclass Folder {\n    String path = \"\"\n    \n    fn init(path) {\n        this.path = path\n    }\n\n    outer async fn create(recursive)\n    outer async fn delete(recursive)\n    outer async fn exists()\n    outer async fn list(recursive)\n    \n    static outer fn current()\n}\n\nclass Http {\n    static outer async fn get(url, headers)\n    static outer async fn post(url, body, headers)\n    static outer async fn put(url, body, headers)\n    static outer async fn delete(url, headers)\n}\n",
    'url': "class URL {\n  auto scheme = null\n  auto host = null\n  auto port = null\n  auto path = null\n  auto query = null\n  auto fragment = null\n  auto userInfo = null\n  auto authority = null\n\n  static outer fn parse(urlString)\n}\n",
    'object': "/// The root class of the Velvet class hierarchy.\n/// Every class in Velvet inherits from Object.\nclass Object{\n    outer fn str string()\n    outer fn num hash()\n}\n\n/// A dynamic, ordered collection of items.\n/// \n/// Lists are 0-indexed and can grow or shrink in size automatically.\nclass List {\n    outer fn add(item)\n    outer fn get(index)\n    outer fn set(index, value)\n    outer fn length()\n    outer fn remove(item)\n    outer fn removeAt(index)\n    outer fn contains(item)\n    outer fn indexOf(item)\n    outer fn clear()\n}\n\n/// A collection of key/value pairs.\n/// Keys must be unique, and retrieving a value by its key is generally fast.\nclass Map {\n    outer fn put(key, value)\n    outer fn get(key)\n    outer fn remove(key)\n    outer fn containsKey(key)\n    outer fn keys()\n    outer fn values()\n    outer fn clear()\n}\n\n/// Represents an error that occurred during runtime.\nclass Error {\n    auto message = \"\"\n    fn init(message) {\n        this.message = message\n    }\n}\n\n/// A sequence of UTF-16 code units representing text.\n/// \n/// Strings are immutable in Velvet.\nclass String {\n    outer fn toUpperCase()\n    outer fn toLowerCase()\n    outer fn length()\n    outer fn trim()\n    outer fn split(pattern)\n    outer fn replace(from, to)\n    outer fn contains(substring)\n    outer fn startsWith(prefix)\n    outer fn endsWith(suffix)\n    outer fn substring(start, end)\n    outer fn isEmpty()\n}\n\n/// An integer or floating-point number.\nclass Number {\n    outer fn toString()\n    outer fn toInt()\n    outer fn toDouble()\n    outer fn round()\n    outer fn floor()\n    outer fn ceil()\n    outer fn abs()\n}\n\n/// Represents a truth value: either true or false.\nclass Boolean {\n    outer fn toString()\n}\n",
    'async': "class Timer {\n    static outer fn sleep(milliseconds)\n}\n",
    'regex': "class RegExp {\n    auto _nativeData = 0\n    fn init(pattern) {\n        this.compile(pattern)\n    }\n    \n    outer fn compile(pattern)\n    outer fn hasMatch(string)\n    outer fn stringMatch(string)\n    outer fn replaceAll(string, replacement)\n}\n",
    'binary': "class Buffer {\n  static outer fn alloc(size)\n  static outer fn fromUtf8(string)\n  outer fn toUtf8()\n  outer fn length()\n  outer fn get(index)\n  outer fn set(index, value)\n}\n",
    'ai': "import \"math.velv\"\nimport \"io.velv\"\nimport \"json.velv\"\n\n/// A simple built-in Artificial Intelligence engine.\n/// \n/// Provides basic algorithms for K-Nearest Neighbors prediction,\n/// K-Means Clustering, Linear Regression, and Recommendation.\nclass SimpleAI {\n    auto _inputs = []\n    auto _outputs = []\n\n    fn init() {}\n\n    // Persistence: Save and Load the Brain\n    async fn save(filepath) {\n        auto map = {\"inputs\": this._inputs, \"outputs\": this._outputs}\n        auto j = new JSON()\n        auto jsonString = j.stringify(map)\n        auto file = new File(filepath)\n        await file.writeAsString(jsonString)\n    }\n\n    async fn load(filepath) {\n        auto file = new File(filepath)\n        auto jsonString = await file.readAsString()\n        auto j = new JSON()\n        auto map = j.parse(jsonString)\n        this._inputs = map.get(\"inputs\")\n        this._outputs = map.get(\"outputs\")\n    }\n\n    // 1. Prediction (K-Nearest Neighbors)\n    fn learn(inputs, outputs) {\n        this._inputs = inputs\n        this._outputs = outputs\n    }\n\n    // 4. Trend Prediction (Linear Regression - Least Squares)\n    // yValues = [100, 200, 300, 400]\n    // futureX = 4 (index for month 5)\n    fn predictTrend(yValues, futureX) {\n        if (yValues.length() < 2) {\n            throw \"Need at least 2 data points for trend prediction!\"\n        }\n        \n        auto n = yValues.length()\n        auto sumX = 0\n        auto sumY = 0\n        auto sumXY = 0\n        auto sumXX = 0\n        \n        auto i = 0\n        while (i < n) {\n            auto x = i\n            auto y = yValues.get(i)\n            sumX = sumX + x\n            sumY = sumY + y\n            sumXY = sumXY + (x * y)\n            sumXX = sumXX + (x * x)\n            i = i + 1\n        }\n        \n        auto denominator = (n * sumXX) - (sumX * sumX)\n        if (denominator == 0) {\n            return yValues.get(n - 1)\n        }\n        \n        auto m = ((n * sumXY) - (sumX * sumY)) / denominator\n        auto b = (sumY - (m * sumX)) / n\n        \n        return (m * futureX) + b\n    }\n\n    fn predict(inputData) {\n        if (this._inputs.length() == 0) {\n            throw \"SimpleAI has not learned anything yet!\"\n        }\n        \n        auto bestDistance = -1\n        auto bestIndex = 0\n        \n        auto i = 0\n        while (i < this._inputs.length()) {\n            auto known = this._inputs.get(i)\n            auto dist = this._euclideanDistance(inputData, known)\n            if (bestDistance == -1 || dist < bestDistance) {\n                bestDistance = dist\n                bestIndex = i\n            }\n            i = i + 1\n        }\n        \n        return this._outputs.get(bestIndex)\n    }\n\n    // 2. Auto-Grouping (K-Means Clustering - 1 Iteration approximation)\n    fn group(dataList, k) {\n        if (dataList.length() == 0) {\n            return []\n        }\n        \n        // Initialize k centroids\n        auto centroids = []\n        auto i = 0\n        while (i < k && i < dataList.length()) {\n            centroids.add(dataList.get(i))\n            i = i + 1\n        }\n        \n        // Assign each data point to closest centroid\n        auto groups = []\n        auto j = 0\n        while (j < k) {\n            groups.add([])\n            j = j + 1\n        }\n        \n        auto d = 0\n        while (d < dataList.length()) {\n            auto point = dataList.get(d)\n            auto bestDist = -1\n            auto bestC = 0\n            \n            auto c = 0\n            while (c < centroids.length()) {\n                auto dist = this._euclideanDistance(point, centroids.get(c))\n                if (bestDist == -1 || dist < bestDist) {\n                    bestDist = dist\n                    bestC = c\n                }\n                c = c + 1\n            }\n            groups.get(bestC).add(point)\n            d = d + 1\n        }\n        \n        return groups\n    }\n\n    // 3. Recommendation (Cosine Similarity / Euclidean approximation)\n    fn recommend(userPreferences, allAvailableItems) {\n        auto bestScore = -1\n        auto bestIndex = 0\n        \n        auto i = 0\n        while (i < allAvailableItems.length()) {\n            auto item = allAvailableItems.get(i)\n            auto dist = this._euclideanDistance(userPreferences, item)\n            \n            if (bestScore == -1 || dist < bestScore) {\n                bestScore = dist\n                bestIndex = i\n            }\n            i = i + 1\n        }\n        return allAvailableItems.get(bestIndex)\n    }\n\n    // Helper Math Function\n    fn _euclideanDistance(a, b) {\n        auto sum = 0\n        auto j = 0\n        while (j < a.length()) {\n            auto diff = a.get(j) - b.get(j)\n            sum = sum + (diff * diff)\n            j = j + 1\n        }\n        return Math.sqrt(sum)\n    }\n}\n",
    'os': "/// Represents an operating system process.\n/// Provides methods to interact with the environment, arguments, and process lifecycle.\nclass Process {\n    static outer fn run(command, args)\n    static outer fn args()\n    static outer fn cwd()\n    static outer fn sleep(milliseconds)\n    static outer fn exit(code)\n}\n\n/// Provides information about the environment in which Velvet is running.\nclass Platform {\n    static outer fn env(key)\n    static outer fn os()\n}\n\n/// A utility class for manipulating file and directory paths.\nclass Path {\n    static outer fn join(part1, part2)\n    static outer fn basename(path)\n    static outer fn dirname(path)\n    static outer fn extension(path)\n}\n\n/// Represents an instant in time.\n/// Provides methods to get the current date and time.\nclass DateTime {\n    static outer fn now()\n    \n    outer fn year()\n    outer fn month()\n    outer fn day()\n    outer fn hour()\n    outer fn minute()\n    outer fn second()\n    outer fn millisecondsSinceEpoch()\n    outer fn toIso8601String()\n}\n\n/// A countdown timer that can be configured to fire once or repeatedly.\nclass Timer {\n    static outer fn periodic(milliseconds, functionName)\n    static outer fn delayed(milliseconds, functionName)\n}\n",
    'collections': "//\n// collections.velv\n// Velvet Collection Library\n//\n// Provides:\n// - Queue\n// - Stack\n// - Set\n// - LinkedList\n// - Collection utilities\n//\n\n\n// ============================================================\n// COLLECTION UTILITIES\n// ============================================================\n\nclass Collections {\n\n    // --------------------------------------------------------\n    // Basic\n    // --------------------------------------------------------\n\n    static fn size(list) {\n        return list.length()\n    }\n\n    static fn isEmpty(list) {\n        return list.length() == 0\n    }\n\n    static fn contains(list, value) {\n\n        loop (list.length(), i) {\n\n            if (list[i] == value) {\n                return true\n            }\n        }\n\n        return false\n    }\n\n    static fn indexOf(list, value) {\n\n        loop (list.length(), i) {\n\n            if (list[i] == value) {\n                return i\n            }\n        }\n\n        return -1\n    }\n\n    static fn first(list) {\n\n        if (list.length() == 0) {\n            throw 'Collection is empty'\n        }\n\n        return list[0]\n    }\n\n    static fn last(list) {\n\n        if (list.length() == 0) {\n            throw 'Collection is empty'\n        }\n\n        return list[list.length() - 1]\n    }\n\n\n    // --------------------------------------------------------\n    // Add / Remove\n    // --------------------------------------------------------\n\n    static fn add(list, value) {\n        list.add(value)\n        return list\n    }\n\n    static fn remove(list, value) {\n\n        auto index = Collections.indexOf(\n            list,\n            value\n        )\n\n        if (index == -1) {\n            return false\n        }\n\n        auto result = []\n\n        loop (list.length(), i) {\n\n            if (i != index) {\n                result.add(list[i])\n            }\n        }\n\n        // Replace original contents\n        while (list.length() > 0) {\n            list.set(\n                list.length() - 1,\n                null\n            )\n        }\n\n        loop (result.length(), i) {\n            list.add(result[i])\n        }\n\n        return true\n    }\n\n\n    // --------------------------------------------------------\n    // Reverse\n    // --------------------------------------------------------\n\n    static fn reverse(list) {\n\n        auto result = []\n\n        auto i = list.length() - 1\n\n        while (i >= 0) {\n\n            result.add(list[i])\n\n            i = i - 1\n        }\n\n        return result\n    }\n\n\n    // --------------------------------------------------------\n    // Copy\n    // --------------------------------------------------------\n\n    static fn copy(list) {\n\n        auto result = []\n\n        loop (list.length(), i) {\n            result.add(list[i])\n        }\n\n        return result\n    }\n\n\n\n\n\n    // --------------------------------------------------------\n    // Join\n    // --------------------------------------------------------\n\n    static fn join(list, separator) {\n\n        auto result = ''\n\n        loop (list.length(), i) {\n\n            if (i > 0) {\n                result = result + separator\n            }\n\n            result = result + list[i].toString()\n        }\n\n        return result\n    }\n\n\n    // --------------------------------------------------------\n    // Numeric operations\n    // --------------------------------------------------------\n\n    static fn sum(list) {\n\n        auto result = 0\n\n        loop (list.length(), i) {\n            result = result + list[i]\n        }\n\n        return result\n    }\n\n    static fn product(list) {\n\n        auto result = 1\n\n        loop (list.length(), i) {\n            result = result * list[i]\n        }\n\n        return result\n    }\n\n    static fn min(list) {\n\n        if (list.length() == 0) {\n            throw 'Collection is empty'\n        }\n\n        auto result = list[0]\n\n        loop (list.length(), i) {\n\n            if (list[i] < result) {\n                result = list[i]\n            }\n        }\n\n        return result\n    }\n\n    static fn max(list) {\n\n        if (list.length() == 0) {\n            throw 'Collection is empty'\n        }\n\n        auto result = list[0]\n\n        loop (list.length(), i) {\n\n            if (list[i] > result) {\n                result = list[i]\n            }\n        }\n\n        return result\n    }\n\n    static fn average(list) {\n\n        if (list.length() == 0) {\n            throw 'Collection is empty'\n        }\n\n        return Collections.sum(list) /\n            list.length()\n    }\n\n\n    // --------------------------------------------------------\n    // Sorting\n    // --------------------------------------------------------\n\n    static fn sort(list) {\n\n        auto result = Collections.copy(list)\n\n        // Insertion sort\n        loop (result.length(), i) {\n\n            auto current = result[i]\n            auto j = i - 1\n\n            while (j >= 0 && result[j] > current) {\n\n                result.set(\n                    j + 1,\n                    result[j]\n                )\n\n                j = j - 1\n            }\n\n            result.set(\n                j + 1,\n                current\n            )\n        }\n\n        return result\n    }\n\n    static fn sortDescending(list) {\n\n        auto result = Collections.copy(list)\n\n        loop (result.length(), i) {\n\n            auto current = result[i]\n            auto j = i - 1\n\n            while (j >= 0 && result[j] < current) {\n\n                result.set(\n                    j + 1,\n                    result[j]\n                )\n\n                j = j - 1\n            }\n\n            result.set(\n                j + 1,\n                current\n            )\n        }\n\n        return result\n    }\n\n\n    // --------------------------------------------------------\n    // Chunk\n    // --------------------------------------------------------\n\n    static fn chunk(list, size) {\n\n        if (size <= 0) {\n            throw 'Chunk size must be greater than zero'\n        }\n\n        auto result = []\n        auto current = []\n\n        loop (list.length(), i) {\n\n            current.add(list[i])\n\n            if (current.length() == size) {\n                result.add(current)\n                current = []\n            }\n        }\n\n        if (current.length() > 0) {\n            result.add(current)\n        }\n\n        return result\n    }\n\n\n    // --------------------------------------------------------\n    // Range\n    // --------------------------------------------------------\n\n    static fn range(start, end) {\n\n        auto result = []\n\n        auto step = 1\n\n        if (start > end) {\n            step = -1\n        }\n\n        auto value = start\n\n        while (\n            (step > 0 && value <= end) ||\n            (step < 0 && value >= end)\n        ) {\n\n            result.add(value)\n\n            value = value + step\n        }\n\n        return result\n    }\n\n\n    // --------------------------------------------------------\n    // Unique\n    // --------------------------------------------------------\n\n    static fn unique(list) {\n\n        auto result = []\n\n        loop (list.length(), i) {\n\n            if (!Collections.contains(\n                result,\n                list[i]\n            )) {\n                result.add(list[i])\n            }\n        }\n\n        return result\n    }\n\n\n    // --------------------------------------------------------\n    // Zip\n    // --------------------------------------------------------\n\n    static fn zip(first, second) {\n\n        auto result = []\n\n        auto size = first.length()\n\n        if (second.length() < size) {\n            size = second.length()\n        }\n\n        loop (size, i) {\n\n            auto pair = []\n\n            pair.add(first[i])\n            pair.add(second[i])\n\n            result.add(pair)\n        }\n\n        return result\n    }\n\n\n    // --------------------------------------------------------\n    // Slice\n    // --------------------------------------------------------\n\n    static fn slice(list, start, end) {\n\n        auto result = []\n\n        auto actualEnd = end\n\n        if (actualEnd > list.length()) {\n            actualEnd = list.length()\n        }\n\n        auto i = start\n\n        while (i < actualEnd) {\n\n            result.add(list[i])\n\n            i = i + 1\n        }\n\n        return result\n    }\n}\n\n\n// ============================================================\n// STACK\n// ============================================================\n\nclass Stack {\n\n    List items = []\n\n    fn init() {\n        this.items = []\n    }\n\n    fn push(value) {\n        this.items.add(value)\n    }\n\n    fn pop() {\n\n        auto size = this.items.length()\n\n        if (size == 0) {\n            throw 'Stack is empty'\n        }\n\n        auto value = this.items[size - 1]\n\n        // Remove last item by rebuilding list\n        auto result = []\n\n        loop (size - 1, i) {\n            result.add(this.items[i])\n        }\n\n        this.items = result\n\n        return value\n    }\n\n    fn peek() {\n\n        if (this.items.length() == 0) {\n            throw 'Stack is empty'\n        }\n\n        return this.items[\n            this.items.length() - 1\n        ]\n    }\n\n    fn isEmpty() {\n        return this.items.length() == 0\n    }\n\n    fn size() {\n        return this.items.length()\n    }\n\n    fn clear() {\n        this.items = []\n    }\n\n    fn values() {\n        return Collections.copy(\n            this.items\n        )\n    }\n}\n\n\n// ============================================================\n// QUEUE\n// ============================================================\n\nclass Queue {\n\n    List items = []\n\n    fn init() {\n        this.items = []\n    }\n\n    fn enqueue(value) {\n        this.items.add(value)\n    }\n\n    fn dequeue() {\n\n        if (this.items.length() == 0) {\n            throw 'Queue is empty'\n        }\n\n        auto value = this.items[0]\n        auto result = []\n\n        loop (this.items.length() - 1, i) {\n            result.add(\n                this.items[i + 1]\n            )\n        }\n\n        this.items = result\n\n        return value\n    }\n\n    fn peek() {\n\n        if (this.items.length() == 0) {\n            throw 'Queue is empty'\n        }\n\n        return this.items[0]\n    }\n\n    fn isEmpty() {\n        return this.items.length() == 0\n    }\n\n    fn size() {\n        return this.items.length()\n    }\n\n    fn clear() {\n        this.items = []\n    }\n\n    fn values() {\n        return Collections.copy(\n            this.items\n        )\n    }\n}\n\n\n// ============================================================\n// SET\n// ============================================================\n\nclass Set {\n\n    List items = []\n\n    fn init() {\n        this.items = []\n    }\n\n    fn add(value) {\n\n        if (!this.contains(value)) {\n            this.items.add(value)\n        }\n    }\n\n    fn remove(value) {\n\n        auto index = this.indexOf(value)\n\n        if (index == -1) {\n            return false\n        }\n\n        auto result = []\n\n        loop (this.items.length(), i) {\n\n            if (i != index) {\n                result.add(\n                    this.items[i]\n                )\n            }\n        }\n\n        this.items = result\n\n        return true\n    }\n\n    fn contains(value) {\n        return Collections.contains(\n            this.items,\n            value\n        )\n    }\n\n    fn indexOf(value) {\n        return Collections.indexOf(\n            this.items,\n            value\n        )\n    }\n\n    fn size() {\n        return this.items.length()\n    }\n\n    fn isEmpty() {\n        return this.items.length() == 0\n    }\n\n    fn clear() {\n        this.items = []\n    }\n\n    fn values() {\n        return Collections.copy(\n            this.items\n        )\n    }\n\n    // A ∪ B\n    fn union(other) {\n\n        auto result = new Set()\n\n        loop (this.items.length(), i) {\n            result.add(this.items[i])\n        }\n\n        loop (other.items.length(), i) {\n            result.add(other.items[i])\n        }\n\n        return result\n    }\n\n    // A ∩ B\n    fn intersection(other) {\n\n        auto result = new Set()\n\n        loop (this.items.length(), i) {\n\n            if (other.contains(\n                this.items[i]\n            )) {\n                result.add(\n                    this.items[i]\n                )\n            }\n        }\n\n        return result\n    }\n\n    // A - B\n    fn difference(other) {\n\n        auto result = new Set()\n\n        loop (this.items.length(), i) {\n\n            if (!other.contains(\n                this.items[i]\n            )) {\n                result.add(\n                    this.items[i]\n                )\n            }\n        }\n\n        return result\n    }\n\n    fn string() {\n        return Collections.join(\n            this.items,\n            ', '\n        )\n    }\n}\n\n\n// ============================================================\n// LINKED LIST\n// ============================================================\n\nclass LinkedListNode {\n\n    auto value = null\n    auto next = null\n\n    fn init(value) {\n        this.value = value\n        this.next = null\n    }\n}\n\n\nclass LinkedList {\n\n    auto head = null\n    auto tail = null\n    Number count = 0\n\n    fn init() {\n        this.head = null\n        this.tail = null\n        this.count = 0\n    }\n\n    fn add(value) {\n\n        auto node = new LinkedListNode(\n            value\n        )\n\n        if (this.head == null) {\n\n            this.head = node\n            this.tail = node\n\n        } else {\n\n            this.tail.next = node\n            this.tail = node\n        }\n\n        this.count = this.count + 1\n    }\n\n    fn addFirst(value) {\n\n        auto node = new LinkedListNode(\n            value\n        )\n\n        node.next = this.head\n        this.head = node\n\n        if (this.tail == null) {\n            this.tail = node\n        }\n\n        this.count = this.count + 1\n    }\n\n    fn removeFirst() {\n\n        if (this.head == null) {\n            throw 'LinkedList is empty'\n        }\n\n        auto value = this.head.value\n\n        this.head = this.head.next\n\n        this.count = this.count - 1\n\n        if (this.count == 0) {\n            this.tail = null\n        }\n\n        return value\n    }\n\n    fn first() {\n\n        if (this.head == null) {\n            throw 'LinkedList is empty'\n        }\n\n        return this.head.value\n    }\n\n    fn last() {\n\n        if (this.tail == null) {\n            throw 'LinkedList is empty'\n        }\n\n        return this.tail.value\n    }\n\n    fn size() {\n        return this.count\n    }\n\n    fn isEmpty() {\n        return this.count == 0\n    }\n\n    fn clear() {\n        this.head = null\n        this.tail = null\n        this.count = 0\n    }\n\n    fn values() {\n\n        auto result = []\n        auto current = this.head\n\n        while (current != null) {\n\n            result.add(\n                current.value\n            )\n\n            current = current.next\n        }\n\n        return result\n    }\n}",
    'math': "//\n// math.velv\n// Velvet Mathematical Core Library\n//\n\n// ============================================================\n// CONSTANTS\n// ============================================================\n\nNumber PI = 3.141592653589793\nNumber E = 2.718281828459045\nNumber TAU = 6.283185307179586\nNumber SQRT_2 = 1.4142135623730951\nNumber SQRT_3 = 1.7320508075688772\nNumber LN_2 = 0.6931471805599453\nNumber LN_10 = 2.302585092994046\n\n\n// ============================================================\n// BASIC MATH\n// ============================================================\n\nclass Math {\n\n    static fn abs(x) {\n        if (x < 0) {\n            return -x\n        }\n\n        return x\n    }\n\n    static fn sign(x) {\n        if (x > 0) {\n            return 1\n        }\n\n        if (x < 0) {\n            return -1\n        }\n\n        return 0\n    }\n\n    static fn min(a, b) {\n        if (a < b) {\n            return a\n        }\n\n        return b\n    }\n\n    static fn max(a, b) {\n        if (a > b) {\n            return a\n        }\n\n        return b\n    }\n\n    static fn clamp(value, minimum, maximum) {\n        if (value < minimum) {\n            return minimum\n        }\n\n        if (value > maximum) {\n            return maximum\n        }\n\n        return value\n    }\n\n    static fn square(x) {\n        return x * x\n    }\n\n    static fn cube(x) {\n        return x * x * x\n    }\n\n    static fn average(a, b) {\n        return (a + b) / 2\n    }\n\n    static fn lerp(a, b, t) {\n        return a + (b - a) * t\n    }\n\n\n// ============================================================\n// POWERS / ROOTS\n// ============================================================\n\n    static fn sqrt(value) {\n        if (value < 0) {\n            throw 'Cannot calculate square root of a negative number'\n        }\n\n        if (value == 0) {\n            return 0\n        }\n\n        auto guess = value\n\n        loop (30, i) {\n            guess = (guess + value / guess) / 2\n        }\n\n        return guess\n    }\n\n    static fn cbrt(value) {\n        if (value == 0) {\n            return 0\n        }\n\n        auto sign = 1\n\n        if (value < 0) {\n            sign = -1\n            value = -value\n        }\n\n        auto guess = value\n\n        loop (30, i) {\n            guess = (\n                2 * guess +\n                value / (guess * guess)\n            ) / 3\n        }\n\n        return guess * sign\n    }\n\n    static fn pow(base, exponent) {\n        if (exponent == 0) {\n            return 1\n        }\n\n        if (base == 0) {\n            return 0\n        }\n\n        if (exponent == Math.floor(exponent)) {\n            auto result = 1\n            auto positiveExponent = exponent\n\n            if (exponent < 0) {\n                positiveExponent = -exponent\n            }\n\n            loop (positiveExponent, i) {\n                result = result * base\n            }\n\n            if (exponent < 0) {\n                return 1 / result\n            }\n\n            return result\n        }\n\n        if (base < 0) {\n            throw 'Fractional powers of negative numbers are not supported'\n        }\n\n        return Math.exp(\n            exponent * Math.ln(base)\n        )\n    }\n\n    static fn squareRoot(value) {\n        return Math.sqrt(value)\n    }\n\n\n// ============================================================\n// ROUNDING\n// ============================================================\n\n    static fn floor(x) {\n        auto i = x.toInt()\n\n        if (x < i) {\n            return i - 1\n        }\n\n        return i\n    }\n\n    static fn ceil(x) {\n        auto i = x.toInt()\n\n        if (x > i) {\n            return i + 1\n        }\n\n        return i\n    }\n\n    static fn round(x) {\n        if (x >= 0) {\n            return Math.floor(x + 0.5)\n        }\n\n        return Math.ceil(x - 0.5)\n    }\n\n    static fn trunc(x) {\n        return x.toInt()\n    }\n\n\n// ============================================================\n// ANGLES\n// ============================================================\n\n    static fn radians(degrees) {\n        return degrees * PI / 180\n    }\n\n    static fn degrees(radians) {\n        return radians * 180 / PI\n    }\n\n    static fn normalizeRadians(angle) {\n        auto turns = Math.floor(angle / TAU)\n\n        angle = angle - turns * TAU\n\n        if (angle > PI) {\n            angle = angle - TAU\n        }\n\n        return angle\n    }\n\n\n// ============================================================\n// TRIGONOMETRY\n// ============================================================\n\n    static fn sin(angle) {\n        auto x = Math.normalizeRadians(angle)\n\n        auto x2 = x * x\n        auto x3 = x2 * x\n        auto x5 = x3 * x2\n        auto x7 = x5 * x2\n        auto x9 = x7 * x2\n        auto x11 = x9 * x2\n        auto x13 = x11 * x2\n\n        return x\n            - x3 / 6\n            + x5 / 120\n            - x7 / 5040\n            + x9 / 362880\n            - x11 / 39916800\n            + x13 / 6227020800\n    }\n\n    static fn cos(angle) {\n        auto x = Math.normalizeRadians(angle)\n\n        auto x2 = x * x\n        auto x4 = x2 * x2\n        auto x6 = x4 * x2\n        auto x8 = x6 * x2\n        auto x10 = x8 * x2\n        auto x12 = x10 * x2\n\n        return 1\n            - x2 / 2\n            + x4 / 24\n            - x6 / 720\n            + x8 / 40320\n            - x10 / 3628800\n            + x12 / 479001600\n    }\n\n    static fn tan(angle) {\n        auto sine = Math.sin(angle)\n        auto cosine = Math.cos(angle)\n\n        if (Math.abs(cosine) < 0.0000000001) {\n            throw 'Tangent is undefined at this angle'\n        }\n\n        return sine / cosine\n    }\n\n\n// ============================================================\n// INVERSE TRIGONOMETRY\n// ============================================================\n\n    static fn atan(x) {\n\n        if (x == 0) {\n            return 0\n        }\n\n        auto sign = 1\n\n        if (x < 0) {\n            sign = -1\n            x = -x\n        }\n\n        auto result = 0\n\n        if (x > 1) {\n            result = PI / 2 - Math.atan(1 / x)\n            return result * sign\n        }\n\n        // atan(x) approximation\n        auto x2 = x * x\n        auto x3 = x2 * x\n        auto x5 = x3 * x2\n        auto x7 = x5 * x2\n        auto x9 = x7 * x2\n        auto x11 = x9 * x2\n\n        result =\n            x\n            - x3 / 3\n            + x5 / 5\n            - x7 / 7\n            + x9 / 9\n            - x11 / 11\n\n        return result * sign\n    }\n\n    static fn atan2(y, x) {\n\n        if (x > 0) {\n            return Math.atan(y / x)\n        }\n\n        if (x < 0 && y >= 0) {\n            return Math.atan(y / x) + PI\n        }\n\n        if (x < 0 && y < 0) {\n            return Math.atan(y / x) - PI\n        }\n\n        if (x == 0 && y > 0) {\n            return PI / 2\n        }\n\n        if (x == 0 && y < 0) {\n            return -PI / 2\n        }\n\n        throw 'atan2 undefined for (0, 0)'\n    }\n\n    static fn asin(x) {\n\n        if (x < -1 || x > 1) {\n            throw 'asin input must be between -1 and 1'\n        }\n\n        if (x == 1) {\n            return PI / 2\n        }\n\n        if (x == -1) {\n            return -PI / 2\n        }\n\n        return Math.atan2(\n            x,\n            Math.sqrt(1 - x * x)\n        )\n    }\n\n    static fn acos(x) {\n\n        if (x < -1 || x > 1) {\n            throw 'acos input must be between -1 and 1'\n        }\n\n        return PI / 2 - Math.asin(x)\n    }\n\n\n// ============================================================\n// EXPONENTIAL / LOGARITHMIC\n// ============================================================\n\n    static fn exp(x) {\n\n        if (x == 0) {\n            return 1\n        }\n\n        auto sign = 1\n\n        if (x < 0) {\n            sign = -1\n            x = -x\n        }\n\n        // Reduce the input.\n        auto n = Math.floor(x / LN_2)\n        auto remainder = x - n * LN_2\n\n        // e^remainder using Taylor series.\n        auto result = 1\n        auto term = 1\n\n        loop (20, i) {\n            term = term * remainder / (i + 1)\n            result = result + term\n        }\n\n        // Multiply by 2^n.\n        auto multiplier = 1\n\n        loop (n, i) {\n            multiplier = multiplier * 2\n        }\n\n        result = result * multiplier\n\n        if (sign < 0) {\n            return 1 / result\n        }\n\n        return result\n    }\n\n    static fn ln(value) {\n\n        if (value <= 0) {\n            throw 'Natural logarithm requires a positive number'\n        }\n\n        auto x = value\n        auto exponent = 0\n\n        // Scale into a numerically useful range.\n        while (x > 2) {\n            x = x / 2\n            exponent = exponent + 1\n        }\n\n        while (x < 1) {\n            x = x * 2\n            exponent = exponent - 1\n        }\n\n        // ln(x) using:\n        // ln(x) = 2 * (z + z^3/3 + z^5/5 + ...)\n        // z = (x - 1)/(x + 1)\n\n        auto z = (x - 1) / (x + 1)\n        auto z2 = z * z\n\n        auto result = 0\n        auto power = z\n\n        loop (20, i) {\n            auto denominator = 2 * i + 1\n\n            result =\n                result +\n                power / denominator\n\n            power = power * z2\n        }\n\n        result = result * 2\n\n        return result + exponent * LN_2\n    }\n\n    static fn log10(value) {\n        return Math.ln(value) / LN_10\n    }\n\n    static fn log2(value) {\n        return Math.ln(value) / LN_2\n    }\n\n\n// ============================================================\n// HYPERBOLIC FUNCTIONS\n// ============================================================\n\n    static fn sinh(x) {\n        auto positive = Math.exp(x)\n        auto negative = Math.exp(-x)\n\n        return (positive - negative) / 2\n    }\n\n    static fn cosh(x) {\n        auto positive = Math.exp(x)\n        auto negative = Math.exp(-x)\n\n        return (positive + negative) / 2\n    }\n\n    static fn tanh(x) {\n        auto e1 = Math.exp(x)\n        auto e2 = Math.exp(-x)\n\n        return (e1 - e2) / (e1 + e2)\n    }\n\n\n// ============================================================\n// DISTANCE / GEOMETRY\n// ============================================================\n\n    static fn distance2D(x1, y1, x2, y2) {\n        auto dx = x2 - x1\n        auto dy = y2 - y1\n\n        return Math.sqrt(\n            dx * dx + dy * dy\n        )\n    }\n\n    static fn distance3D(\n        x1,\n        y1,\n        z1,\n        x2,\n        y2,\n        z2\n    ) {\n        auto dx = x2 - x1\n        auto dy = y2 - y1\n        auto dz = z2 - z1\n\n        return Math.sqrt(\n            dx * dx +\n            dy * dy +\n            dz * dz\n        )\n    }\n\n    static fn hypot(x, y) {\n        return Math.sqrt(\n            x * x + y * y\n        )\n    }\n\n\n// ============================================================\n// COMBINATORICS\n// ============================================================\n\n    static fn factorial(n) {\n\n        if (n < 0) {\n            throw 'Factorial requires a non-negative integer'\n        }\n\n        if (n != Math.floor(n)) {\n            throw 'Factorial requires an integer'\n        }\n\n        auto result = 1\n\n        loop (n, i) {\n            result = result * (i + 1)\n        }\n\n        return result\n    }\n\n    static fn permutation(n, r) {\n\n        if (n < 0 || r < 0 || r > n) {\n            throw 'Invalid permutation values'\n        }\n\n        return Math.factorial(n) /\n            Math.factorial(n - r)\n    }\n\n    static fn combination(n, r) {\n\n        if (n < 0 || r < 0 || r > n) {\n            throw 'Invalid combination values'\n        }\n\n        return Math.factorial(n) /\n            (Math.factorial(r) * Math.factorial(n - r))\n    }\n\n\n// ============================================================\n// GCD / LCM\n// ============================================================\n\n    static fn gcd(a, b) {\n\n        a = Math.abs(a)\n        b = Math.abs(b)\n\n        while (b != 0) {\n            auto remainder =\n                a - Math.floor(a / b) * b\n\n            a = b\n            b = remainder\n        }\n\n        return a\n    }\n\n    static fn lcm(a, b) {\n\n        if (a == 0 || b == 0) {\n            return 0\n        }\n\n        return Math.abs(\n            a * b\n        ) / Math.gcd(a, b)\n    }\n\n\n// ============================================================\n// INTERPOLATION\n// ============================================================\n\n    static fn smoothstep(edge0, edge1, x) {\n\n        auto t = Math.clamp((x - edge0) / (edge1 - edge0), 0, 1)\n\n        return t * t * (\n            3 - 2 * t\n        )\n    }\n\n    static fn smootherstep(edge0, edge1, x) {\n\n        auto t = Math.clamp((x - edge0) / (edge1 - edge0), 0, 1)\n\n        return t * t * t * (\n            t * (\n                t * 6 - 15\n            ) + 10\n        )\n    }\n}",
    'http_server': "/// A web server that listens for HTTP requests.\nclass HttpServer {\n    /// Binds an HTTP server to the specified [host] and [port].\n    static outer async fn bind(host, port)\n\n    /// Waits for the next incoming HTTP request.\n    /// Returns an HttpRequest object.\n    outer async fn accept()\n\n    /// Closes the server.\n    outer async fn close()\n}\n\n/// Represents an incoming HTTP request.\nclass HttpRequest {\n    /// The HTTP method (e.g., 'GET', 'POST').\n    outer fn method()\n\n    /// The requested URI as a string.\n    outer fn uri()\n\n    /// The path component of the requested URI.\n    outer fn path()\n\n    /// Gets the URL query parameters as a Map.\n    outer fn query()\n\n    /// Gets the request headers as a Map.\n    outer fn headers()\n\n    /// Gets the IP address of the client making the request.\n    outer fn ip()\n\n    /// Gets the HttpResponse object associated with this request.\n    outer fn response()\n\n    /// Reads the entire request body as a string.\n    outer async fn readAsString()\n\n    /// Reads the entire request body as raw bytes (Buffer).\n    outer async fn readAsBytes()\n\n    /// Parses the request body as JSON and returns a Velvet Map/List.\n    outer async fn parseJson()\n\n    /// Parses the request body as URL-encoded form data and returns a Map.\n    outer async fn parseFormUrlEncoded()\n\n    /// Parses the request body as multipart/form-data.\n    /// Returns a Map where values are either Strings or Maps (for file uploads with 'filename' and 'bytes').\n    outer async fn parseMultipart()\n}\n\n/// Represents an HTTP response sent back to the client.\nclass HttpResponse {\n    /// Gets the HTTP status code.\n    outer fn statusCode()\n\n    /// Sets the HTTP status code (e.g., 200, 404).\n    outer fn setStatusCode(code)\n\n    /// Sets an HTTP header.\n    outer fn setHeader(name, value)\n\n    /// Removes an HTTP header.\n    outer fn removeHeader(name)\n\n    /// Writes string data to the response body.\n    outer fn write(data)\n\n    /// Writes raw bytes (Buffer) to the response body.\n    outer fn writeBytes(buffer)\n\n    /// Closes the response, sending the data to the client.\n    outer async fn close()\n}\n",
    'statistics': "//\n// statistics.velv\n// Velvet Statistics Library\n//\n\nimport \"bin/velvet_core/math.velv\"\n\n\nclass Statistics {\n\n    // ========================================================\n    // BASIC\n    // ========================================================\n\n    static fn count(values) {\n        return values.length()\n    }\n\n    static fn sum(values) {\n\n        auto total = 0\n\n        loop (values.length(), i) {\n            total = total + values[i]\n        }\n\n        return total\n    }\n\n    static fn min(values) {\n\n        if (values.length() == 0) {\n            throw 'Cannot calculate minimum of empty collection'\n        }\n\n        auto result = values[0]\n\n        loop (values.length(), i) {\n\n            if (values[i] < result) {\n                result = values[i]\n            }\n        }\n\n        return result\n    }\n\n    static fn max(values) {\n\n        if (values.length() == 0) {\n            throw 'Cannot calculate maximum of empty collection'\n        }\n\n        auto result = values[0]\n\n        loop (values.length(), i) {\n\n            if (values[i] > result) {\n                result = values[i]\n            }\n        }\n\n        return result\n    }\n\n    static fn range(values) {\n        return Statistics.max(values) -\n            Statistics.min(values)\n    }\n\n\n    // ========================================================\n    // MEAN\n    // ========================================================\n\n    static fn mean(values) {\n\n        if (values.length() == 0) {\n            throw 'Cannot calculate mean of empty collection'\n        }\n\n        return Statistics.sum(values) /\n            values.length()\n    }\n\n\n    // ========================================================\n    // MEDIAN\n    // ========================================================\n\n    static fn median(values) {\n\n        if (values.length() == 0) {\n            throw 'Cannot calculate median of empty collection'\n        }\n\n        auto sorted = Statistics.sort(values)\n        auto size = sorted.length()\n        auto middle = Math.floor(size / 2)\n\n        // Avoid using % because Velvet does not\n        // currently define the modulo operator.\n\n        auto half = Math.floor(size / 2)\n\n        if (half * 2 == size) {\n\n            return (\n                sorted[middle - 1] +\n                sorted[middle]\n            ) / 2\n        }\n\n        return sorted[middle]\n    }\n\n\n    // ========================================================\n    // MODE\n    // ========================================================\n\n    static fn mode(values) {\n\n        if (values.length() == 0) {\n            throw 'Cannot calculate mode of empty collection'\n        }\n\n        auto bestValue = values[0]\n        auto bestCount = 0\n\n        loop (values.length(), i) {\n\n            auto current = values[i]\n            auto count = 0\n\n            loop (values.length(), j) {\n\n                if (values[j] == current) {\n                    count = count + 1\n                }\n            }\n\n            if (count > bestCount) {\n                bestCount = count\n                bestValue = current\n            }\n        }\n\n        return bestValue\n    }\n\n\n    // ========================================================\n    // VARIANCE\n    // ========================================================\n\n    // Population variance:\n    //\n    // σ² = Σ(x - μ)² / N\n\n    static fn variance(values) {\n\n        if (values.length() == 0) {\n            throw 'Cannot calculate variance of empty collection'\n        }\n\n        auto average = Statistics.mean(values)\n        auto total = 0\n\n        loop (values.length(), i) {\n\n            auto difference =\n                values[i] - average\n\n            total =\n                total +\n                difference * difference\n        }\n\n        return total / values.length()\n    }\n\n\n    // ========================================================\n    // SAMPLE VARIANCE\n    // ========================================================\n\n    // Sample variance:\n    //\n    // s² = Σ(x - x̄)² / (N - 1)\n\n    static fn sampleVariance(values) {\n\n        if (values.length() < 2) {\n            throw 'Sample variance requires at least 2 values'\n        }\n\n        auto average = Statistics.mean(values)\n        auto total = 0\n\n        loop (values.length(), i) {\n\n            auto difference =\n                values[i] - average\n\n            total =\n                total +\n                difference * difference\n        }\n\n        return total / (\n            values.length() - 1\n        )\n    }\n\n\n    // ========================================================\n    // STANDARD DEVIATION\n    // ========================================================\n\n    static fn standardDeviation(values) {\n\n        return Math.sqrt(\n            Statistics.variance(values)\n        )\n    }\n\n    static fn sampleStandardDeviation(values) {\n\n        return Math.sqrt(\n            Statistics.sampleVariance(values)\n        )\n    }\n\n\n    // ========================================================\n    // PERCENTILES\n    // ========================================================\n\n    static fn percentile(values, percent) {\n\n        if (values.length() == 0) {\n            throw 'Cannot calculate percentile of empty collection'\n        }\n\n        if (percent < 0 || percent > 100) {\n            throw 'Percentile must be between 0 and 100'\n        }\n\n        auto sorted = Statistics.sort(values)\n\n        if (sorted.length() == 1) {\n            return sorted[0]\n        }\n\n        auto position =\n            (percent / 100) *\n            (sorted.length() - 1)\n\n        auto lower =\n            Math.floor(position)\n\n        auto upper =\n            lower + 1\n\n        if (upper >= sorted.length()) {\n            return sorted[lower]\n        }\n\n        auto fraction =\n            position - lower\n\n        return sorted[lower] +\n            (\n                sorted[upper] -\n                sorted[lower]\n            ) * fraction\n    }\n\n\n    static fn quartile1(values) {\n\n        return Statistics.percentile(\n            values,\n            25\n        )\n    }\n\n\n    static fn quartile2(values) {\n\n        return Statistics.percentile(\n            values,\n            50\n        )\n    }\n\n\n    static fn quartile3(values) {\n\n        return Statistics.percentile(\n            values,\n            75\n        )\n    }\n\n\n    static fn interquartileRange(values) {\n\n        return Statistics.quartile3(values) -\n            Statistics.quartile1(values)\n    }\n\n\n    // ========================================================\n    // Z-SCORE\n    // ========================================================\n\n    static fn zScore(value, values) {\n\n        auto average =\n            Statistics.mean(values)\n\n        auto deviation =\n            Statistics.standardDeviation(values)\n\n        if (deviation == 0) {\n            throw 'Standard deviation cannot be zero'\n        }\n\n        return (\n            value - average\n        ) / deviation\n    }\n\n\n    // ========================================================\n    // COVARIANCE\n    // ========================================================\n\n    static fn covariance(x, y) {\n\n        if (x.length() != y.length()) {\n            throw 'Collections must have the same length'\n        }\n\n        if (x.length() == 0) {\n            throw 'Collections cannot be empty'\n        }\n\n        auto meanX =\n            Statistics.mean(x)\n\n        auto meanY =\n            Statistics.mean(y)\n\n        auto total = 0\n\n        loop (x.length(), i) {\n\n            auto dx =\n                x[i] - meanX\n\n            auto dy =\n                y[i] - meanY\n\n            total =\n                total +\n                dx * dy\n        }\n\n        return total / x.length()\n    }\n\n\n    // ========================================================\n    // SAMPLE COVARIANCE\n    // ========================================================\n\n    static fn sampleCovariance(x, y) {\n\n        if (x.length() != y.length()) {\n            throw 'Collections must have the same length'\n        }\n\n        if (x.length() < 2) {\n            throw 'At least 2 values are required'\n        }\n\n        auto meanX =\n            Statistics.mean(x)\n\n        auto meanY =\n            Statistics.mean(y)\n\n        auto total = 0\n\n        loop (x.length(), i) {\n\n            auto dx =\n                x[i] - meanX\n\n            auto dy =\n                y[i] - meanY\n\n            total =\n                total +\n                dx * dy\n        }\n\n        return total / (\n            x.length() - 1\n        )\n    }\n\n\n    // ========================================================\n    // PEARSON CORRELATION\n    // ========================================================\n\n    static fn correlation(x, y) {\n\n        if (x.length() != y.length()) {\n            throw 'Collections must have the same length'\n        }\n\n        if (x.length() == 0) {\n            throw 'Collections cannot be empty'\n        }\n\n        auto meanX =\n            Statistics.mean(x)\n\n        auto meanY =\n            Statistics.mean(y)\n\n        auto numerator = 0\n        auto sumX = 0\n        auto sumY = 0\n\n        loop (x.length(), i) {\n\n            auto dx =\n                x[i] - meanX\n\n            auto dy =\n                y[i] - meanY\n\n            numerator =\n                numerator +\n                dx * dy\n\n            sumX =\n                sumX +\n                dx * dx\n\n            sumY =\n                sumY +\n                dy * dy\n        }\n\n        auto denominator =\n            Math.sqrt(\n                sumX * sumY\n            )\n\n        if (denominator == 0) {\n            throw 'Correlation undefined when variance is zero'\n        }\n\n        return numerator / denominator\n    }\n\n\n    // ========================================================\n    // MEAN ABSOLUTE DEVIATION\n    // ========================================================\n\n    static fn meanAbsoluteDeviation(values) {\n\n        if (values.length() == 0) {\n            throw 'Cannot calculate deviation of empty collection'\n        }\n\n        auto average =\n            Statistics.mean(values)\n\n        auto total = 0\n\n        loop (values.length(), i) {\n\n            total =\n                total +\n                Math.abs(\n                    values[i] - average\n                )\n        }\n\n        return total / values.length()\n    }\n\n\n    // ========================================================\n    // ROOT MEAN SQUARE\n    // ========================================================\n\n    static fn rootMeanSquare(values) {\n\n        if (values.length() == 0) {\n            throw 'Cannot calculate RMS of empty collection'\n        }\n\n        auto total = 0\n\n        loop (values.length(), i) {\n\n            total =\n                total +\n                values[i] * values[i]\n        }\n\n        return Math.sqrt(\n            total / values.length()\n        )\n    }\n\n\n    // ========================================================\n    // WEIGHTED MEAN\n    // ========================================================\n\n    static fn weightedMean(values, weights) {\n\n        if (values.length() != weights.length()) {\n            throw 'Values and weights must have the same length'\n        }\n\n        if (values.length() == 0) {\n            throw 'Collections cannot be empty'\n        }\n\n        auto total = 0\n        auto weightTotal = 0\n\n        loop (values.length(), i) {\n\n            total =\n                total +\n                values[i] * weights[i]\n\n            weightTotal =\n                weightTotal +\n                weights[i]\n        }\n\n        if (weightTotal == 0) {\n            throw 'Sum of weights cannot be zero'\n        }\n\n        return total / weightTotal\n    }\n\n\n    // ========================================================\n    // SORT\n    // ========================================================\n\n    static fn sort(values) {\n\n        auto result = []\n\n        loop (values.length(), i) {\n            result.add(values[i])\n        }\n\n        // Insertion sort\n\n        loop (result.length(), i) {\n\n            auto current =\n                result[i]\n\n            auto j = i - 1\n\n            while (\n                j >= 0 &&\n                result[j] > current\n            ) {\n\n                result.set(\n                    j + 1,\n                    result[j]\n                )\n\n                j = j - 1\n            }\n\n            result.set(\n                j + 1,\n                current\n            )\n        }\n\n        return result\n    }\n\n\n    // ========================================================\n    // FREQUENCY\n    // ========================================================\n\n    static fn frequency(values, target) {\n\n        auto count = 0\n\n        loop (values.length(), i) {\n\n            if (values[i] == target) {\n                count = count + 1\n            }\n        }\n\n        return count\n    }\n\n\n    // ========================================================\n    // NORMALIZE\n    // ========================================================\n\n    static fn normalize(value, minimum, maximum) {\n\n        if (maximum == minimum) {\n            throw 'Maximum and minimum cannot be equal'\n        }\n\n        return (\n            value - minimum\n        ) / (\n            maximum - minimum\n        )\n    }\n\n\n    // ========================================================\n    // SKEWNESS\n    // ========================================================\n\n    static fn skewness(values) {\n\n        if (values.length() < 2) {\n            throw 'At least 2 values are required'\n        }\n\n        auto average =\n            Statistics.mean(values)\n\n        auto deviation =\n            Statistics.standardDeviation(values)\n\n        if (deviation == 0) {\n            throw 'Skewness undefined when standard deviation is zero'\n        }\n\n        auto total = 0\n\n        loop (values.length(), i) {\n\n            auto normalized =\n                (\n                    values[i] - average\n                ) / deviation\n\n            total =\n                total +\n                normalized *\n                normalized *\n                normalized\n        }\n\n        return total / values.length()\n    }\n\n\n    // ========================================================\n    // SUMMARY\n    // ========================================================\n\n    static fn summary(values) {\n\n        if (values.length() == 0) {\n            throw 'Cannot summarize empty collection'\n        }\n\n        Map result = {}\n\n        result['count'] =\n            Statistics.count(values)\n\n        result['sum'] =\n            Statistics.sum(values)\n\n        result['mean'] =\n            Statistics.mean(values)\n\n        result['median'] =\n            Statistics.median(values)\n\n        result['mode'] =\n            Statistics.mode(values)\n\n        result['min'] =\n            Statistics.min(values)\n\n        result['max'] =\n            Statistics.max(values)\n\n        result['range'] =\n            Statistics.range(values)\n\n        result['variance'] =\n            Statistics.variance(values)\n\n        result['standardDeviation'] =\n            Statistics.standardDeviation(values)\n\n        result['quartile1'] =\n            Statistics.quartile1(values)\n\n        result['quartile3'] =\n            Statistics.quartile3(values)\n\n        result['interquartileRange'] =\n            Statistics.interquartileRange(values)\n\n        return result\n    }\n}",
    'random': "import \"math.velv\"\n\n// Native binding to dart:math Random\nclass NativeRandom {\n    static outer fn create()\n    static outer fn createWithSeed(seed)\n    static outer fn nextDouble(nativeRnd)\n    static outer fn nextInt(nativeRnd, max)\n    static outer fn nextBool(nativeRnd)\n}\n\n//\n// random.velv\n// Velvet Random Number Library\n//\n// Wraps dart:math's high-quality Random generator.\n//\n\nclass Random {\n\n    auto _native = false\n\n    fn init() {\n        this._native = NativeRandom.create()\n    }\n\n    fn seed(value) {\n        this._native = NativeRandom.createWithSeed(value)\n    }\n\n    fn next() {\n        return NativeRandom.nextDouble(this._native)\n    }\n\n    fn boolean() {\n        return NativeRandom.nextBool(this._native)\n    }\n\n    fn double(minimum, maximum) {\n        if (maximum < minimum) {\n            throw 'Maximum cannot be less than minimum'\n        }\n\n        if (maximum == minimum) {\n            return minimum\n        }\n\n        return minimum + this.next() * (maximum - minimum)\n    }\n\n    fn int(minimum, maximum) {\n        if (maximum < minimum) {\n            throw 'Maximum cannot be less than minimum'\n        }\n\n        if (maximum == minimum) {\n            return minimum.toInt()\n        }\n\n        auto range = maximum.toInt() - minimum.toInt() + 1\n        return minimum.toInt() + NativeRandom.nextInt(this._native, range)\n    }\n\n    fn choice(list) {\n        if (list.length() == 0) {\n            throw 'Cannot choose from an empty list'\n        }\n        return list[NativeRandom.nextInt(this._native, list.length())]\n    }\n\n    fn index(length) {\n        if (length <= 0) {\n            throw 'Length must be greater than zero'\n        }\n        return NativeRandom.nextInt(this._native, length)\n    }\n\n    fn shuffle(list) {\n        auto result = []\n        loop (list.length(), i) {\n            result.add(list[i])\n        }\n\n        // Fisher-Yates shuffle\n        auto i = result.length() - 1\n        while (i > 0) {\n            auto j = NativeRandom.nextInt(this._native, i + 1)\n            auto temp = result[i]\n            result.set(i, result[j])\n            result.set(j, temp)\n            i = i - 1\n        }\n        return result\n    }\n\n    fn take(list) {\n        if (list.length() == 0) {\n            throw 'Cannot take from an empty list'\n        }\n        return list[NativeRandom.nextInt(this._native, list.length())]\n    }\n\n    fn sign() {\n        if (this.boolean()) {\n            return 1\n        }\n        return -1\n    }\n\n    fn chance(percent) {\n        if (percent <= 0) {\n            return false\n        }\n        if (percent >= 100) {\n            return true\n        }\n        return this.next() < (percent / 100)\n    }\n\n    fn hexColor() {\n        auto red = this.int(0, 255)\n        auto green = this.int(0, 255)\n        auto blue = this.int(0, 255)\n\n        return '#' + Random.hex(red) + Random.hex(green) + Random.hex(blue)\n    }\n\n    static fn hex(value) {\n        auto digits = '0123456789ABCDEF'\n        auto high = Math.floor(value / 16)\n        auto low = value - high * 16\n\n        return digits.substring(high, high + 1) + digits.substring(low, low + 1)\n    }\n}",
    'dns': "class DNS {\n  static outer async fn lookup(host)\n}\n",
    'websocket': "class WebSocketClient {\n    static outer async fn connect(url)\n    outer async fn send(data)\n    outer async fn receive()\n    outer async fn close()\n}\n\nclass WebSocketServer {\n    static outer async fn bind(host, port)\n    outer async fn accept()\n    outer async fn close()\n}\n",
    'ffi': "class FFI {\n    static outer fn load(path, libName)\n    static outer fn invokeVoid(libName, funcName)\n    static outer fn invokeInt(libName, funcName, arg)\n    static outer fn invokeString(libName, funcName, arg)\n}\n",
    'socket': "class Socket {\n  static outer async fn connect(host, port)\n  outer async fn write(data)\n  outer async fn writeAsBytes(buffer)\n  outer async fn read()\n  outer async fn readAsBytes()\n  outer async fn close()\n}\n\nclass ServerSocket {\n  static outer async fn bind(host, port)\n  outer async fn accept()\n  outer async fn close()\n}\n",
  };
}
